#ifndef FILE_MDHTML_MD_JS_RUNTIME_H_
#define FILE_MDHTML_MD_JS_RUNTIME_H_

#include <quickjs.h>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <functional>
#include <string>
#include <string_view>
#include <vector>

// Internal header: exposes QuickJS types to the core engines only. Public
// qlitemd headers never include this file.

// One qjsc-generated bytecode payload (see md_bytecode.h).
struct MdJsPayload {
  const uint8_t* data = nullptr;
  uint32_t size = 0;
  const char* name = nullptr;
};

struct MdJsEngineStatus {
  bool loaded = false;
  bool permanently_failed = false;
  int64_t first_load_ms = 0;
};

// Lifecycle of a QuickJS runtime/context: bytecode loading, one-shot failure
// semantics, first-load timing and an interrupt flag. One instance per
// worker thread.
class MdJsRuntime {
 public:
  MdJsRuntime() = default;
  ~MdJsRuntime();
  MdJsRuntime(const MdJsRuntime&) = delete;
  MdJsRuntime& operator=(const MdJsRuntime&) = delete;

  // prepare runs before the payloads (register C functions, install the
  // bridge), after_load after them (expose globals). Either returning false
  // permanently fails the engine.
  bool EnsureLoaded(const std::vector<MdJsPayload>& payloads,
                    const std::function<bool(JSContext*)>& prepare,
                    const std::function<bool(JSContext*)>& after_load);

  bool Eval(std::string_view code, const char* script_name,
            std::string* error = nullptr);

  JSContext* context() const { return context_; }
  JSRuntime* runtime() const { return runtime_; }
  MdJsEngineStatus status() const;

  void set_on_fail(std::function<void(JSContext*)> on_fail);
  void SetRuntimeOpaque(void* opaque);
  // Keep an already measured first-load time even when a later step fails
  // (Mermaid initialize semantics).
  void set_preserve_first_load(bool preserve);
  void Abort();

  // The flag is owned by the caller and must outlive the runtime. Setting it
  // makes QuickJS throw an uncatchable interrupted exception on the owning
  // thread.
  void SetInterruptFlag(std::atomic<bool>* flag);

  // Drops the runtime after cancellation so a later job can reload it.
  void ResetForReload();

  static std::string TakeExceptionMessage(JSContext* context);
  static bool CheckResult(JSContext* context, JSValue value,
                          std::string_view label, std::string* error);

 private:
  bool FailLoad();

  JSRuntime* runtime_ = nullptr;
  JSContext* context_ = nullptr;
  bool load_failed_ = false;
  bool load_attempted_ = false;
  int64_t first_load_ms_ = 0;
  std::chrono::steady_clock::time_point load_start_;
  std::function<void(JSContext*)> on_fail_;
  bool preserve_first_load_ = false;
  std::atomic<bool>* interrupt_flag_ = nullptr;
  void* runtime_opaque_ = nullptr;
};

#endif  // FILE_MDHTML_MD_JS_RUNTIME_H_
